import{_ as n,C as s,o,c as l,j as e,a as t,E as r,a8 as d}from"./chunks/framework.27XeWUA0.js";const k=JSON.parse('{"title":"S Anand Talks · Archive","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"archive","routine":"talks"},"relativePath":"talks/archive.md","filePath":"talks/[date].md"}'),c={name:"talks/archive.md"},h={id:"s-anand-talks-·-archive",tabindex:"-1"};function p(u,a,g,m,b,v){const i=s("Badge");return o(),l("div",null,[e("h1",h,[a[0]||(a[0]=t("S Anand Talks · Archive ",-1)),r(i,{type:"tip",text:"75"}),a[1]||(a[1]=t()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#s-anand-talks-·-archive","aria-label":'Permalink to "S Anand Talks · Archive <Badge type="tip" text="75" />"'},"​",-1))]),a[3]||(a[3]=d('<p class="sub">75 talks already listed when tracking started. Sorted by talk date.</p><ol class="talks"><li id="t-2026-10-12-tds-ideation" data-title="The Exam Is a Hypothesis"><span class="meta">12 Oct 2026</span> <a href="https://sanand0.github.io/talks/2026-10-12-tds-ideation/" target="_blank" rel="noopener">The Exam Is a Hypothesis</a><div class="meta">Recorded open TDS (IIT Madras) course-design meeting with students; principles for AI-agent-proof assessments (six tests, move the missing piece, check the checker, test for transfer). Video 69m, transcript, audio 69m, blog.</div></li><li id="t-2026-10-07-iitm-ed-data-visualization" data-title="Looks Right. Isn&#39;t."><span class="meta">07 Oct 2026</span> <a href="https://sanand0.github.io/talks/2026-10-07-iitm-ed-data-visualization/" target="_blank" rel="noopener">Looks Right. Isn&#39;t.</a><div class="meta">AI makes pictures cheap to create but harder to trust: the reader may be another AI, and a chart, map or CAD model that looks right still needs an independent check.</div></li><li id="t-2026-10-05-tds-orientation" data-title="Get the Job Done — and Verify It"><span class="meta">05 Oct 2026</span> <a href="https://sanand0.github.io/talks/2026-10-05-tds-orientation/" target="_blank" rel="noopener">Get the Job Done — and Verify It</a><div class="meta">TDS treats exams as the curriculum and agents as executors: students learn to specify, orchestrate, collaborate, notice, adapt and verify while the tools keep changing.</div></li><li id="t-2026-10-01-use-ai-emperically" data-title="Let&#39;s Test: Use AI Empirically"><span class="meta">01 Oct 2026</span> <a href="https://sanand0.github.io/talks/2026-10-01-use-ai-emperically/" target="_blank" rel="noopener">Let&#39;s Test: Use AI Empirically</a><div class="meta">Treat AI advice, models and agent workflows as hypotheses: test them on your own work, mine your logs for evidence, and make verification part of the workflow.</div></li><li id="t-2026-09-24-iis-ph-evidence-to-impact" data-title="If You&#39;re Too Excited, Don&#39;t Forget to Verify"><span class="meta">24 Sep 2026</span> <a href="https://sanand0.github.io/talks/2026-09-24-iis-ph-evidence-to-impact/" target="_blank" rel="noopener">If You&#39;re Too Excited, Don&#39;t Forget to Verify</a><div class="meta">AI is too weird and fast-moving to trust by intuition alone: question advice, verify with a second model, calibrate confidence, benchmark what matters, and turn surviving evidence into deterministic rules.</div></li><li id="t-2026-09-19-shree-niketan-schools" data-title="Even the AI Guy Couldn&#39;t Find the Chat Button"><span class="meta">19 Sep 2026</span> <a href="https://sanand0.github.io/talks/2026-09-19-shree-niketan-schools/" target="_blank" rel="noopener">Even the AI Guy Couldn&#39;t Find the Chat Button</a><div class="meta">Treat AI as a collaborator, not a vending machine: ask it to interview you before it builds a lesson plan, log what actually happens after you use its output, and benchmark any fix before trusting it.</div></li><li id="t-2026-09-06-how-to-build-ai-products" data-title="How to Build AI Products — and Prove They Work"><span class="meta">11 Sep 2026</span> <a href="https://sanand0.github.io/talks/2026-09-06-how-to-build-ai-products/" target="_blank" rel="noopener">How to Build AI Products — and Prove They Work</a><div class="meta">Build AI products around evidence, not ideas: prototype quickly, test with agents and real users, and iterate until the product proves its value.</div></li><li id="t-2026-09-03-convergence-jio-institute" data-title="What&#39;s Left For Us"><span class="meta">03 Sep 2026</span> <a href="https://sanand0.github.io/talks/2026-09-03-convergence-jio-institute/" target="_blank" rel="noopener">What&#39;s Left For Us</a><div class="meta">As AI takes over production, human value shifts to judgment, context, and verification. The real bottleneck is the cost of checking AI&#39;s work.</div></li><li id="t-2026-08-22-ai-unboxed-vibe-coding" data-title="You Don&#39;t Even Need to Code"><span class="meta">22 Aug 2026</span> <a href="https://sanand0.github.io/talks/2026-08-22-ai-unboxed-vibe-coding/" target="_blank" rel="noopener">You Don&#39;t Even Need to Code</a><div class="meta">Coding is becoming specification and review: describe the outcome, let agents build it, and focus on whether the result works.</div></li><li id="t-2026-08-12-iitm-ed-data-visualization" data-title="Why Are You Even Sitting in This Class?"><span class="meta">12 Aug 2026</span> <a href="https://sanand0.github.io/talks/2026-08-12-iitm-ed-data-visualization/" target="_blank" rel="noopener">Why Are You Even Sitting in This Class?</a><div class="meta">AI can generate charts and analysis. The enduring skill is knowing what deserves to be visualized, challenged, and communicated.</div></li><li id="t-2026-08-10-tds-ama" data-title="What Is This Course Really Teaching?"><span class="meta">10 Aug 2026</span> <a href="https://sanand0.github.io/talks/2026-08-10-tds-ama/" target="_blank" rel="noopener">What Is This Course Really Teaching?</a><div class="meta">Tools change faster than curricula. The course is really about learning how to learn, automate work, and judge results rather than memorizing tools.</div></li><li id="t-2026-08-07-data-hack-summit" data-title="How Do You Manage Something Smarter Than You?"><span class="meta">07 Aug 2026</span> <a href="https://sanand0.github.io/talks/2026-08-07-data-hack-summit/" target="_blank" rel="noopener">How Do You Manage Something Smarter Than You?</a><div class="meta">Managing AI resembles managing experts: specify work clearly, verify outputs systematically, and borrow proven practices from professions that already manage complex judgment.</div></li><li id="t-2026-07-25-ai-unboxed-agentic-analysis" data-title="Hire a Data Scientist for $100"><span class="meta">25 Jul 2026</span> <a href="https://sanand0.github.io/talks/2026-07-25-ai-unboxed-agentic-analysis/" target="_blank" rel="noopener">Hire a Data Scientist for $100</a><div class="meta">Agentic tools can perform much of a data scientist&#39;s research and analysis cheaply. The leverage comes from framing the question and checking the result.</div></li><li id="t-2026-07-09-ai-for-school-teachers" data-title="Invite AI to the Table"><span class="meta">09 Jul 2026</span> <a href="https://sanand0.github.io/talks/2026-07-09-ai-for-school-teachers/" target="_blank" rel="noopener">Invite AI to the Table</a><div class="meta">Teachers should use AI as a participant in lesson planning, explanation, assessment, and reflection—not treat it as a separate subject or shortcut.</div></li><li id="t-2026-07-07-when-data-is-for-agents-fifth-elephant" data-title="When Data is for Agents, Not Humans"><span class="meta">07 Jul 2026</span> <a href="https://sanand0.github.io/talks/2026-07-07-when-data-is-for-agents-fifth-elephant/" target="_blank" rel="noopener">When Data is for Agents, Not Humans</a><div class="meta">Data increasingly serves agents rather than dashboards. Structure it so agents can research, analyze, benchmark, and act reliably on behalf of people.</div></li><li id="t-2026-07-04-vizchitra-dialog-curators-dilemma" data-title="The Curator&#39;s Dilemma"><span class="meta">04 Jul 2026</span> <a href="https://sanand0.github.io/talks/2026-07-04-vizchitra-dialog-curators-dilemma/" target="_blank" rel="noopener">The Curator&#39;s Dilemma</a><div class="meta">When AI makes charts abundant, curation—not production—becomes scarce: deciding what deserves attention, what is trustworthy, and what fits the audience.</div></li><li id="t-2026-07-02-iimb-mda-workshop" data-title="Free Methods, Priced Judgment"><span class="meta">02 Jul 2026</span> <a href="https://sanand0.github.io/talks/2026-07-02-iimb-mda-workshop/" target="_blank" rel="noopener">Free Methods, Priced Judgment</a><div class="meta">AI makes sophisticated analytical methods cheap and accessible. The scarce skill becomes choosing the right analysis, questioning assumptions, and judging whether results matter.</div></li><li id="t-2026-06-20-ai-unboxed-tools-workflows" data-title="The Workshop That Made Itself"><span class="meta">20 Jun 2026</span> <a href="https://sanand0.github.io/talks/2026-06-20-ai-unboxed-tools-workflows/" target="_blank" rel="noopener">The Workshop That Made Itself</a><div class="meta">AI can design and execute workflows while a session is running. The useful skill is orchestrating tools, context, and verification rather than following a fixed script.</div></li><li id="t-2026-06-16-eqt-data-stack-for-agents" data-title="The Data Stack for an Agentic World"><span class="meta">16 Jun 2026</span> <a href="https://sanand0.github.io/talks/2026-06-16-eqt-data-stack-for-agents/" target="_blank" rel="noopener">The Data Stack for an Agentic World</a><div class="meta">Data stacks should be designed for agents, not dashboards: expose granular data and judgment-rich context so agents can aggregate and reason for each question.</div></li><li id="t-2026-06-13-data-stories-with-ai" data-title="Data Stories with AI"><span class="meta">13 Jun 2026</span> <a href="https://sanand0.github.io/talks/2026-06-13-data-stories-with-ai/" target="_blank" rel="noopener">Data Stories with AI</a><div class="meta">AI can turn raw data into analyses, narratives, visuals, and alternative explanations. The craft shifts to questioning, verification, and editorial judgment.</div></li><li id="t-2026-06-12-let-ai-take-your-exams" data-title="Let AI Take Your Exams"><span class="meta">12 Jun 2026</span> <a href="https://sanand0.github.io/talks/2026-06-12-let-ai-take-your-exams/" target="_blank" rel="noopener">Let AI Take Your Exams</a><div class="meta">If AI can pass an exam, the exam may be measuring the wrong thing. Assessments should reward effective AI use, verification, and real-world outcomes.</div></li><li id="t-2026-06-11-engineering-design-iitm" data-title="The Moving Boundary"><span class="meta">11 Jun 2026</span> <a href="https://sanand0.github.io/talks/2026-06-11-engineering-design-iitm/" target="_blank" rel="noopener">The Moving Boundary</a><div class="meta">AI keeps moving the boundary between disciplines and automation. Education should organize around problems and judgment rather than fixed departmental skill boxes.</div></li><li id="t-2026-05-23-ai-unboxed-context-engineering" data-title="What Your AI Doesn&#39;t Know About You"><span class="meta">23 May 2026</span> <a href="https://sanand0.github.io/talks/2026-05-23-ai-unboxed-context-engineering/" target="_blank" rel="noopener">What Your AI Doesn&#39;t Know About You</a><div class="meta">AI performance depends less on clever prompts than on context. Give models the right goals, examples, constraints, history, and tools so they can act effectively.</div></li><li id="t-2026-05-15-gramener-all-hands" data-title="Agents are the New Software"><span class="meta">15 May 2026</span> <a href="https://sanand0.github.io/talks/2026-05-15-gramener-all-hands/" target="_blank" rel="noopener">Agents are the New Software</a><div class="meta">Software is shifting from fixed interfaces and workflows to agents that interpret goals and choose actions dynamically. Products should be designed around delegated outcomes.</div></li><li id="t-2026-04-30-harvard-education" data-title="Inventing the Future of Learning"><span class="meta">30 Apr 2026</span> <a href="https://sanand0.github.io/talks/2026-04-30-harvard-education/" target="_blank" rel="noopener">Inventing the Future of Learning</a><div class="meta">AI breaks the old link between learning, producing work, and proving competence. Education must redesign practice and assessment around what humans should still learn and demonstrate.</div></li><li id="t-2026-04-22-the-dinner-table-theory-of-ai-skills" data-title="The Dinner Table Theory of AI Skills"><span class="meta">22 Apr 2026</span> <a href="https://sanand0.github.io/talks/2026-04-22-the-dinner-table-theory-of-ai-skills/" target="_blank" rel="noopener">The Dinner Table Theory of AI Skills</a><div class="meta">AI makes traditional signals of competence easy to fake. Skills and assessments should focus on valuable questions, validation, accountability, and outcomes AI cannot certify for us.</div></li><li id="t-2026-04-08-ai-workshop-lbsnaa" data-title="A Thousand Professors In Your Pocket"><span class="meta">08 Apr 2026</span> <a href="https://sanand0.github.io/talks/2026-04-08-ai-workshop-lbsnaa/" target="_blank" rel="noopener">A Thousand Professors In Your Pocket</a><div class="meta">Everyone now has access to an endlessly patient expert. The opportunity is to use AI as a tutor and thinking partner while building habits for checking its mistakes.</div></li><li id="t-2026-04-08-frontiers-in-technology-debjani-lbsnaa" data-title="Frontiers in Technology"><span class="meta">08 Apr 2026</span> <a href="https://sanand0.github.io/talks/2026-04-08-frontiers-in-technology-debjani-lbsnaa/" target="_blank" rel="noopener">Frontiers in Technology</a><div class="meta">Government leaders need to anticipate frontier technologies years before they mainstream. Today&#39;s policy, R&amp;D, and capability investments determine whether India leads or catches up.</div></li><li id="t-2026-04-06-innovation-as-a-frontier-straive" data-title="Innovation as a Frontier"><span class="meta">06 Apr 2026</span> <a href="https://sanand0.github.io/talks/2026-04-06-innovation-as-a-frontier-straive/" target="_blank" rel="noopener">Innovation as a Frontier</a><div class="meta">Innovation is frontier exploration, not a pipeline with a known destination. Leaders should fund cheap experiments, learn quickly, and expand what becomes possible.</div></li><li id="t-2026-03-26-hack-of-the-day-toi" data-title="The Journalist and the Machine"><span class="meta">26 Mar 2026</span> <a href="https://sanand0.github.io/talks/2026-03-26-hack-of-the-day-toi/" target="_blank" rel="noopener">The Journalist and the Machine</a><div class="meta">Journalists can use AI to turn curiosity into rapid experiments and explainers. The machine accelerates research and production; editorial judgment decides what is worth publishing.</div></li><li id="t-2026-03-21-faculty-ai-transformation-nie" data-title="The McKinsey in Your Pocket"><span class="meta">21 Mar 2026</span> <a href="https://sanand0.github.io/talks/2026-03-21-faculty-ai-transformation-nie/" target="_blank" rel="noopener">The McKinsey in Your Pocket</a><div class="meta">AI gives individuals on-demand access to research, analysis, and structured advice once reserved for expert teams. Institutions should redesign work around that new leverage.</div></li><li id="t-2026-03-21-design-in-the-age-of-infinite-generativity" data-title="Design in the Age of Infinite Generativity"><span class="meta">21 Mar 2026</span> <a href="https://sanand0.github.io/talks/2026-03-21-design-in-the-age-of-infinite-generativity/" target="_blank" rel="noopener">Design in the Age of Infinite Generativity</a><div class="meta">When AI can generate endless options, design shifts from making artifacts to choosing constraints, framing problems, and deciding what should exist.</div></li><li id="t-2026-03-18-verifiable-agents" data-title="Verification Architecture for Autonomous AI"><span class="meta">18 Mar 2026</span> <a href="https://sanand0.github.io/talks/2026-03-18-verifiable-agents/" target="_blank" rel="noopener">Verification Architecture for Autonomous AI</a><div class="meta">Autonomous agents are useful only when their actions can be trusted. Constrain workflows, verify intermediate outputs, and design explicit checks before granting autonomy.</div></li><li id="t-2026-03-18-iitm-office-of-institutional-advancement" data-title="AI for IITM Office of Institutional Advancement"><span class="meta">18 Mar 2026</span> <a href="https://sanand0.github.io/talks/2026-03-18-iitm-office-of-institutional-advancement/" target="_blank" rel="noopener">AI for IITM Office of Institutional Advancement</a><div class="meta">AI can automate research, outreach, personalization, and analysis in institutional advancement. The largest gains come from redesigning workflows rather than adding a chatbot.</div></li><li id="t-2026-03-18-iitm-academic-council" data-title="The Open-Book Exam We Never Designed"><span class="meta">18 Mar 2026</span> <a href="https://sanand0.github.io/talks/2026-03-18-iitm-academic-council/" target="_blank" rel="noopener">The Open-Book Exam We Never Designed</a><div class="meta">When every student has a powerful AI tutor and solver, conventional closed-book assumptions collapse. Assessments must measure judgment, verification, and application instead.</div></li><li id="t-2026-03-15-pyconf-ai-in-sdlc" data-title="AI in SDLC — Panel Discussion"><span class="meta">15 Mar 2026</span> <a href="https://sanand0.github.io/talks/2026-03-15-pyconf-ai-in-sdlc/" target="_blank" rel="noopener">AI in SDLC — Panel Discussion</a><div class="meta">AI is entering every stage of software development. Teams need to redesign the SDLC around faster generation, stronger automated checks, and human accountability.</div></li><li id="t-2026-03-15-how-students-learn-python" data-title="How Students Learn Python"><span class="meta">15 Mar 2026</span> <a href="https://sanand0.github.io/talks/2026-03-15-how-students-learn-python/" target="_blank" rel="noopener">How Students Learn Python</a><div class="meta">Students increasingly learn Python by asking AI, copying examples, and debugging interactively. Teaching should embrace these paths while preserving conceptual understanding and verification.</div></li><li id="t-2026-03-12-nie-ai-roadmap" data-title="AI Roadmap for Engineering Education"><span class="meta">12 Mar 2026</span> <a href="https://sanand0.github.io/talks/2026-03-12-nie-ai-roadmap/" target="_blank" rel="noopener">AI Roadmap for Engineering Education</a><div class="meta">Engineering education should treat AI as infrastructure across the curriculum, not a standalone elective. Courses, assessment, and faculty workflows all need redesign.</div></li><li id="t-2026-02-26-vibe-coding-for-humanities-ashoka" data-title="Vibe Coding for Humanities"><span class="meta">26 Feb 2026</span> <a href="https://sanand0.github.io/talks/2026-02-26-vibe-coding-for-humanities-ashoka/" target="_blank" rel="noopener">Vibe Coding for Humanities</a><div class="meta">Coding agents let humanities students build software without becoming programmers. The valuable skill is expressing intent clearly and critically evaluating what the machine produces.</div></li><li id="t-2026-02-11-amat-dt-day" data-title="Your Chotu Is Smarter Than You Think"><span class="meta">11 Feb 2026</span> <a href="https://sanand0.github.io/talks/2026-02-11-amat-dt-day/" target="_blank" rel="noopener">Your Chotu Is Smarter Than You Think</a><div class="meta">Modern AI is capable enough to handle surprisingly broad knowledge work. Treat it like a smart junior colleague: delegate aggressively, then review where it matters.</div></li><li id="t-2026-01-20-agentic-ai-in-action-deloitte" data-title="Agentic AI in Action"><span class="meta">20 Jan 2026</span> <a href="https://sanand0.github.io/talks/2026-01-20-agentic-ai-in-action-deloitte/" target="_blank" rel="noopener">Agentic AI in Action</a><div class="meta">Agents turn LLMs from answer generators into workers that use tools, execute multi-step tasks, and recover from failures. The challenge is control and verification.</div></li><li id="t-2026-01-11-nptel-vibe-coding-workshop" data-title="Applied Vibe Coding"><span class="meta">11 Jan 2026</span> <a href="https://sanand0.github.io/talks/2026-01-11-nptel-vibe-coding-workshop/" target="_blank" rel="noopener">Applied Vibe Coding</a><div class="meta">Vibe coding treats code as a disposable build artifact. Specify the outcome, let agents implement it, and spend your effort reviewing behavior rather than typing code.</div></li><li id="t-2025-12-06-mining-digital-exhaust" data-title="Mining Digital Exhaust"><span class="meta">06 Dec 2025</span> <a href="https://sanand0.github.io/talks/2025-12-06-mining-digital-exhaust/" target="_blank" rel="noopener">Mining Digital Exhaust</a><div class="meta">Everyday digital traces—chats, logs, histories, submissions—contain valuable signals. LLMs make it practical to mine them for patterns, stories, and decisions.</div></li><li id="t-2025-12-05-scdm-keynote" data-title="Data to Decisions with AI"><span class="meta">05 Dec 2025</span> <a href="https://sanand0.github.io/talks/2025-12-05-scdm-keynote/" target="_blank" rel="noopener">Data to Decisions with AI</a><div class="meta">LLMs can automate expensive clinical-data work from protocol checks to anomaly detection and enrollment analysis, provided verification is designed into the workflow.</div></li><li id="t-2025-12-03-vibe-analytics-iim-alumni-sg" data-title="Vibe Analytics"><span class="meta">03 Dec 2025</span> <a href="https://sanand0.github.io/talks/2025-12-03-vibe-analytics-iim-alumni-sg/" target="_blank" rel="noopener">Vibe Analytics</a><div class="meta">Vibe analysis lets AI handle code and analytical mechanics while you focus on useful questions, surprising insights, verification, and what action follows.</div></li><li id="t-2025-11-15-applied-vibe-coding" data-title="Applied Vibe Coding"><span class="meta">15 Nov 2025</span> <a href="https://sanand0.github.io/talks/2025-11-15-applied-vibe-coding/" target="_blank" rel="noopener">Applied Vibe Coding</a><div class="meta">With coding agents, specifications become the product and code becomes cheap. Work faster by delegating implementation, testing aggressively, and optimizing for review.</div></li><li id="t-2025-11-13-nirmal-impress-ai-hr" data-title="AI First Thinking for HR Professionals"><span class="meta">13 Nov 2025</span> <a href="https://sanand0.github.io/talks/2025-11-13-nirmal-impress-ai-hr/" target="_blank" rel="noopener">AI First Thinking for HR Professionals</a><div class="meta">AI-first HR means redesigning work, not adding a chatbot. Better questions, structured context, process re-engineering, and AI as a first-class participant matter more.</div></li><li id="t-2025-11-06-llm-psychology" data-title="LLM Psychology"><span class="meta">06 Nov 2025</span> <a href="https://sanand0.github.io/talks/2025-11-06-llm-psychology/" target="_blank" rel="noopener">LLM Psychology</a><div class="meta">LLM psychology treats models as minds to probe: test how prompts, personalities, costs, and failure modes change behavior, then use evidence to choose and manage them.</div></li><li id="t-2025-10-29-llm-data-visualization" data-title="LLM Data Visualization"><span class="meta">29 Oct 2025</span> <a href="https://sanand0.github.io/talks/2025-10-29-llm-data-visualization/" target="_blank" rel="noopener">LLM Data Visualization</a><div class="meta">LLMs can generate, interpret, and even invent visualizations. The analyst&#39;s role shifts toward asking better questions, testing novelty, and judging whether a visual is useful.</div></li><li id="t-2025-10-23-vibe-coding" data-title="Vibe Coding"><span class="meta">23 Oct 2025</span> <a href="https://sanand0.github.io/talks/2025-10-23-vibe-coding/" target="_blank" rel="noopener">Vibe Coding</a><div class="meta">Vibe coding focuses on outcomes rather than code. Give agents clear requirements and enough context, let them implement, and judge delivered behavior instead of implementation details.</div></li><li id="t-2025-10-16-vibe-analysis" data-title="Vibe Analysis"><span class="meta">16 Oct 2025</span> <a href="https://sanand0.github.io/talks/2025-10-16-vibe-analysis/" target="_blank" rel="noopener">Vibe Analysis</a><div class="meta">Vibe analysis delegates the analytical process to agents and focuses humans on business outcomes. Explore broadly, verify key claims, and automate successful analyses afterward.</div></li><li id="t-2025-09-22-llm-trends" data-title="LLM Trends"><span class="meta">22 Sep 2025</span> <a href="https://sanand0.github.io/talks/2025-09-22-llm-trends/" target="_blank" rel="noopener">LLM Trends</a><div class="meta">LLMs are becoming cheaper, smarter, longer-context, more autonomous, and more multimodal at once. Each trend makes previously bespoke workflows practical to automate.</div></li><li id="t-2025-09-21-making-open-data-useful" data-title="Making Open Data Useful: Lessons from Diagram Chasing"><span class="meta">21 Sep 2025</span> <a href="https://sanand0.github.io/talks/2025-09-21-making-open-data-useful/" target="_blank" rel="noopener">Making Open Data Useful: Lessons from Diagram Chasing</a><div class="meta">Open data is useful only when people can find, understand, trust, and reuse it. Good interfaces, validation, documentation, and reproducible pipelines turn publication into utility.</div></li><li id="t-2025-09-21-zainab-building-a-culture-of-openness" data-title="Building a culture of openness"><span class="meta">21 Sep 2025</span> <a href="https://sanand0.github.io/talks/2025-09-21-zainab-building-a-culture-of-openness/" target="_blank" rel="noopener">Building a culture of openness</a><div class="meta">Open peer review can turn conference selection into community learning. Clear roles, public feedback, scoped incentives, and measurable outcomes make openness sustainable.</div></li><li id="t-2025-09-20-kiran-homelabbing-with-bare-metal" data-title="Homelabbing with Bare Metal"><span class="meta">20 Sep 2025</span> <a href="https://sanand0.github.io/talks/2025-09-20-kiran-homelabbing-with-bare-metal/" target="_blank" rel="noopener">Homelabbing with Bare Metal</a><div class="meta">Homelabbing works best when hardware is low-power, modular, and easy to reconfigure. Iterative DIY rigs make experimentation cheap enough to follow curiosity.</div></li><li id="t-2025-09-18-llm-ama-bi-worldwide" data-title="LLMs: Ask me anything"><span class="meta">18 Sep 2025</span> <a href="https://sanand0.github.io/talks/2025-09-18-llm-ama-bi-worldwide/" target="_blank" rel="noopener">LLMs: Ask me anything</a><div class="meta">AI is becoming cheap, capable infrastructure. Use it heavily, manage it like a large team of smart interns, and build verification into the work.</div></li><li id="t-2025-09-16-vibe-analysis" data-title="Vibe Analysis"><span class="meta">16 Sep 2025</span> <a href="https://sanand0.github.io/talks/2025-09-16-vibe-analysis/" target="_blank" rel="noopener">Vibe Analysis</a><div class="meta">Vibe analysis uses LLM agents across the full data workflow while humans stay pragmatic and skeptical: seek useful outcomes, challenge them, and publish reproducible work.</div></li><li id="t-2025-09-15-llm-ama-gale" data-title="LLMs: Ask me anything"><span class="meta">15 Sep 2025</span> <a href="https://sanand0.github.io/talks/2025-09-15-llm-ama-gale/" target="_blank" rel="noopener">LLMs: Ask me anything</a><div class="meta">AI capability is improving far faster than organizational adoption. Use it now, focus on practical outcomes, and expect culture, trust, and workflow redesign to be harder than technology.</div></li><li id="t-2025-09-13-duckdb-is-the-new-pandas" data-title="DuckDB is the new Pandas"><span class="meta">13 Sep 2025</span> <a href="https://sanand0.github.io/talks/2025-09-13-duckdb-is-the-new-pandas/" target="_blank" rel="noopener">DuckDB is the new Pandas</a><div class="meta">DuckDB offers a simpler, faster analytical default than Pandas for many workloads: SQL, low memory use, remote files, rich functions, and embedded deployment.</div></li><li id="t-2025-08-21-ai-coding-guide" data-title="AI Coding Guide"><span class="meta">21 Aug 2025</span> <a href="https://sanand0.github.io/talks/2025-08-21-ai-coding-guide/" target="_blank" rel="noopener">AI Coding Guide</a><div class="meta">AI coding works best when repositories are easy for agents to understand, tasks are well-scoped, tests are fast, and humans review outcomes rather than keystrokes.</div></li><li id="t-2025-08-21-rip-data-scientists" data-title="RIP Data Scientists"><span class="meta">21 Aug 2025</span> <a href="https://sanand0.github.io/talks/2025-08-21-rip-data-scientists/" target="_blank" rel="noopener">RIP Data Scientists</a><div class="meta">Almost every task a data scientist does today can be automated using LLMs. The role of data scientists must change.</div></li><li id="t-2025-08-11-social-code-analysis" data-title="Social Code Analysis"><span class="meta">11 Aug 2025</span> <a href="https://sanand0.github.io/talks/2025-08-11-social-code-analysis/" target="_blank" rel="noopener">Social Code Analysis</a><div class="meta">Code can be analyzed socially, not just technically: repository behavior, collaboration patterns, and AI-based evaluation reveal how people build software and where process breaks.</div></li><li id="t-2025-07-24-pugs-agent-loop" data-title="Cool LLM CLI Python uses — with agents"><span class="meta">24 Jul 2025</span> <a href="https://sanand0.github.io/talks/2025-07-24-pugs-agent-loop/" target="_blank" rel="noopener">Cool LLM CLI Python uses — with agents</a><div class="meta">LLM command-line workflows can automate everyday Python tasks, then grow into agents that execute code and perform reliable calculations with tools like Pydantic AI.</div></li><li id="t-2025-07-23-supply-chain-automl" data-title="Solving Industrial Problems with Live Coding"><span class="meta">23 Jul 2025</span> <a href="https://sanand0.github.io/talks/2025-07-23-supply-chain-automl/" target="_blank" rel="noopener">Solving Industrial Problems with Live Coding</a><div class="meta">LLMs can turn messy industrial and IoT data into working analyses live, collapsing the gap between domain question, code, model, and decision.</div></li><li id="t-2025-07-18-tug-true-but-irrelevant-rob-schrauwen" data-title="True but Irrelevant"><span class="meta">18 Jul 2025</span> <a href="https://sanand0.github.io/talks/2025-07-18-tug-true-but-irrelevant-rob-schrauwen/" target="_blank" rel="noopener">True but Irrelevant</a><div class="meta">Rigid schemas can be technically correct yet operationally irrelevant. Preserve provenance, annotate assertions separately, and model the data people actually produce.</div></li><li id="t-2025-07-13-goodbye-mba-hello-ai" data-title="Goodbye MBA, Hello AI"><span class="meta">13 Jul 2025</span> <a href="https://sanand0.github.io/talks/2025-07-13-goodbye-mba-hello-ai/" target="_blank" rel="noopener">Goodbye MBA, Hello AI</a><div class="meta">AI is a foundational shift for managers: analytical and production work gets cheaper, so advantage moves to problem selection, judgment, communication, and organizational change.</div></li><li id="t-2025-06-28-prompt-to-plot" data-title="Prompt-to-Plot"><span class="meta">28 Jun 2025</span> <a href="https://sanand0.github.io/talks/2025-06-28-prompt-to-plot/" target="_blank" rel="noopener">Prompt-to-Plot</a><div class="meta">LLMs can move from a natural-language question to data, analysis, and a finished visualization. The challenge is specifying intent and validating the resulting chart.</div></li><li id="t-2025-06-27-data-design-by-dialogue" data-title="Data Design by Dialogue"><span class="meta">27 Jun 2025</span> <a href="https://sanand0.github.io/talks/2025-06-27-data-design-by-dialogue/" target="_blank" rel="noopener">Data Design by Dialogue</a><div class="meta">Data visualization can become a dialogue with AI: explore alternative charts, critique them, and iterate conversationally until the design communicates the right idea.</div></li><li id="t-2025-06-pycon-sg-llm-cli-html" data-title="Cool LLM CLI Python uses"><span class="meta">19 Jun 2025</span> <a href="https://sanand0.github.io/talks/2025-06-pycon-sg/llm-cli.html" target="_blank" rel="noopener">Cool LLM CLI Python uses</a><div class="meta">LLM command-line tools make Python automation conversational: inspect files, transform data, call APIs, and compose workflows by describing the result you want.</div></li><li id="t-2025-06-pycon-sg" data-title="Python in the Browser"><span class="meta">18 Jun 2025</span> <a href="https://sanand0.github.io/talks/2025-06-pycon-sg/" target="_blank" rel="noopener">Python in the Browser</a><div class="meta">Modern browsers can run substantial Python locally, making interactive tools easier to distribute: many applications need no server, installation, or backend.</div></li><li id="t-2025-01-18-how-to-use-ai-to-generate-code" data-title="How to use AI to generate code?"><span class="meta">18 Jan 2025</span> <a href="https://sanand0.github.io/talks/2025-01-18-how-to-use-ai-to-generate-code/" target="_blank" rel="noopener">How to use AI to generate code?</a><div class="meta">AI can generate useful software from plain-language instructions. Start with small outcomes, iterate on failures, and treat generated code as something to test rather than trust.</div></li><li id="t-2024-10-19-ai-in-education-webinar" data-title="AI as a learning tool: What students, teachers, and parents need to know"><span class="meta">19 Oct 2024</span> <a href="https://sanand0.github.io/talks/2024-10-19-ai-in-education-webinar/" target="_blank" rel="noopener">AI as a learning tool: What students, teachers, and parents need to know</a><div class="meta">AI can personalize explanation, practice, and feedback for students and teachers, but effective use depends on critical thinking, ethics, and checking what the system produces.</div></li><li id="t-2022-03-07-career-principles-with-rajen-makhijani" data-title="The Accomplished Beginner"><span class="meta">07 Mar 2022</span> <a href="https://sanand0.github.io/talks/2022-03-07-career-principles-with-rajen-makhijani/" target="_blank" rel="noopener">The Accomplished Beginner</a><div class="meta">A portfolio career requires becoming an accomplished beginner again and again: experiment with one foot, combine disciplines, and use past accomplishments as confidence rather than status.</div></li><li id="t-2022-02-20-it-doesnt-have-to-be-us-and-them-rajen-makhijani" data-title="The Glass Wall of Class"><span class="meta">20 Feb 2022</span> <a href="https://sanand0.github.io/talks/2022-02-20-it-doesnt-have-to-be-us-and-them-rajen-makhijani/" target="_blank" rel="noopener">The Glass Wall of Class</a><div class="meta">Class divides make other people&#39;s choices look irrational because their context is invisible. Crossing the glass wall builds empathy and reveals shared human motives.</div></li><li id="t-2015-02-28-tedx-nmims-bangalore" data-title="Visualizing Politics"><span class="meta">28 Feb 2015</span> <a href="https://sanand0.github.io/talks/2015-02-28-tedx-nmims-bangalore/" target="_blank" rel="noopener">Visualizing Politics</a><div class="meta">Archive migration: full talk page &quot;The Strangest Row&quot; for TEDx NMIMS Bangalore 2015 (YouTube: Data, Politics and Anomalies). Interactive story + comic with 13m video; chapters with timestamps; transcript, audio, slides; claim-vs-record verification table. Election-data anomalies (Modakurichi 1,033 candidates, etc.). Format differs from recent TDS/video talks — long written narrative with verification notes.</div></li></ol>',2))])}const y=n(c,[["render",p]]);export{k as __pageData,y as default};
